svg.script:
(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  function first(n) { return document.getElementsByTagNameNS(XHTML, n)[0] || null; }
  Object.defineProperty(document, "body", { configurable: true, get: function () { return first("body"); } });
  Object.defineProperty(document, "head", { configurable: true, get: function () { return first("head"); } });

  document.createElement = function (n) {
    return document.createElementNS(XHTML, String(n).toLowerCase());
  };

  var H = document.implementation.createHTMLDocument("");
  var innerDesc = Object.getOwnPropertyDescriptor(Element.prototype, "innerHTML");
  function parseHTML(v) {
    var t = H.createElement("template");
    innerDesc.set.call(t, v);
    return Array.prototype.map.call(t.content.childNodes, function (n) {
      return document.importNode(n, true);
    });
  }
  Object.defineProperty(Element.prototype, "innerHTML", {
    configurable: true,
    get: innerDesc.get,
    set: function (v) {
      if (this.ownerDocument !== document) return innerDesc.set.call(this, v);
      while (this.firstChild) this.removeChild(this.firstChild);
      var self = this;
      parseHTML(v).forEach(function (n) { self.appendChild(n); });
    }
  });
  Element.prototype.insertAdjacentHTML = function (pos, v) {
    var self = this, nodes = parseHTML(v), ref;
    switch (String(pos).toLowerCase()) {
      case "beforebegin": nodes.forEach(function (n) { self.parentNode.insertBefore(n, self); }); break;
      case "afterbegin": ref = self.firstChild; nodes.forEach(function (n) { self.insertBefore(n, ref); }); break;
      case "beforeend": nodes.forEach(function (n) { self.appendChild(n); }); break;
      case "afterend": ref = self.nextSibling; nodes.forEach(function (n) { self.parentNode.insertBefore(n, ref); }); break;
    }
  };
})();
